package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

final class SignedEventsAcceptance {
 static final String API="/api/openservice/integration-profiles";
 static String path(String profile){return "/api/openservice/inbound-events/incident/"+profile;}
 static Map<String,Object> config(int revision){return map("revision",revision,"active",true,"definition",map("name","Monitoring intake","table","incident","gateway_username","EventGateway","fields",List.of("short_description","description","priority")));}
 static String[] setup(WorkflowSupport h)throws Exception {
  String user,token;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","EventGateway","password",PASSWORD,"role","agent"));user=RecordAccess.owner(db,"EventGateway");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",user);token=ApiKeyWrites.issue(db,db.viewerId,user,map("label","Signed event gateway","table","incident","days",1)).get("token").toString();db.connection.commit();}var result=result(h.json("POST",API,config(0),auth("admin")));return new String[]{object(result.get("profile")).get("profile_id").toString(),result.get("issued_secret").toString(),token,user};
 }
 static Map<String,Object> payload(){return map("fields",map("short_description","Signed monitoring alert <script>","description","Provider evidence","priority","2"));}
 static String signature(String secret,String timestamp,String id,String event,byte[] bytes)throws Exception {var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));mac.update(timestamp.getBytes(StandardCharsets.UTF_8));mac.update(("\n"+id+"\n"+event+"\n").getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(mac.doFinal(bytes));}
 static HttpResponse<byte[]> raw(WorkflowSupport h,String path,byte[] bytes,String type,String authorization,List<String> events,List<String> times,List<String> signatures)throws Exception {var req=HttpRequest.newBuilder(URI.create(h.base()+path)).header("X-OpenService-API","true");if(type!=null)req.header("Content-Type",type);if(authorization!=null)req.header("Authorization",authorization);for(String x:events)req.header("X-OpenService-Event",x);for(String x:times)req.header("X-OpenService-Timestamp",x);for(String x:signatures)req.header("X-OpenService-Signature",x);return h.client.send(req.POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.ofByteArray());}
 static HttpResponse<byte[]> send(WorkflowSupport h,String[] ids,String event,Object input)throws Exception {byte[] bytes=JSON.writeValueAsBytes(input);String time=Long.toString(System.currentTimeMillis()/1000);return raw(h,path(ids[0]),bytes,"application/json","Bearer "+ids[2],List.of(event),List.of(time),List.of(signature(ids[1],time,ids[0],event,bytes)));}
 static void run(WorkflowSupport h)throws Exception {
  var ids=setup(h);assertTrue(ids[1].startsWith("osw_"));assertFalse(html(h.get(API+"/"+ids[0],auth("admin"))).contains(ids[1]));EventWorkflowsAcceptance.configure(h,EventWorkflowsAcceptance.config(0,"created","1",List.of(EventWorkflowsAcceptance.note())));var first=result(send(h,ids,"alert-1",payload()));assertEquals(false,first.get("duplicate"));String record=object(first.get("record")).get("sys_id").toString();assertEquals("2",object(first.get("record")).get("priority"));assertEquals(true,result(send(h,ids,"alert-1",payload())).get("duplicate"));assertEquals(record,object(result(send(h,ids,"alert-1",payload())).get("record")).get("sys_id"));var changed=payload();object(changed.get("fields")).put("description","Changed alert");assertEquals(409,send(h,ids,"alert-1",changed).statusCode());EventWorkflowsAcceptance.tick(h.store);assertEquals("succeeded",EventWorkflowsAcceptance.run(h,record).get("state"));new Store(h.environment);assertEquals(true,result(send(h,ids,"alert-1",payload())).get("duplicate"));var page=result(h.get(API+"/"+ids[0],auth("admin")));assertEquals(1,((Number)page.get("total")).intValue());assertEquals(1,objects(page.get("receipts")).size());assertFalse(JSON.writeValueAsString(page).contains("envelope"));try(var db=h.store.open()){assertFalse(db.one("SELECT envelope FROM os_signed_profile WHERE profile_id=?",ids[0]).get("envelope").toString().contains(ids[1]));assertFalse(JSON.writeValueAsString(db.all("SELECT detail FROM os_security_event")).contains(ids[1]));}
  var replacement=config(1);object(replacement.get("definition")).put("name","Changed used profile");assertEquals(409,h.json("POST",API+"/"+ids[0],replacement,auth("admin")).statusCode());var rotated=result(h.json("POST",API+"/"+ids[0],map("revision",1,"operation","rotate"),auth("admin")));assertNotEquals(ids[1],rotated.get("issued_secret"));assertEquals(403,send(h,ids,"new-after-rotation",payload()).statusCode());ids[1]=rotated.get("issued_secret").toString();assertEquals(true,result(send(h,ids,"alert-1",payload())).get("duplicate"));assertEquals(1,objects(result(h.get(API+"/"+ids[0],auth("admin"))).get("receipts")).getFirst().get("profile_revision"));
  assertEquals(204,h.json("DELETE","/api/now/table/incident/"+record,map(),auth("admin")).statusCode());assertEquals(404,send(h,ids,"alert-1",payload()).statusCode());assertTrue(object(objects(result(h.get(API+"/"+ids[0],auth("admin"))).get("receipts")).getFirst().get("record")).isEmpty());
 }
 static void boundaries(WorkflowSupport h)throws Exception {
  var ids=setup(h);byte[] bytes=JSON.writeValueAsBytes(payload());String now=Long.toString(System.currentTimeMillis()/1000),event="edge",sig=signature(ids[1],now,ids[0],event,bytes),bearer="Bearer "+ids[2];assertEquals(401,raw(h,path(ids[0]),bytes,"application/json",null,List.of(event),List.of(now),List.of(sig)).statusCode());assertEquals(403,raw(h,path(ids[0]),bytes,"application/json",auth("admin"),List.of(event),List.of(now),List.of(sig)).statusCode());assertEquals(403,h.get(path(ids[0]),bearer).statusCode());assertEquals(400,raw(h,path(ids[0])+"?extra=1",bytes,"application/json",bearer,List.of(event),List.of(now),List.of(sig)).statusCode());
  for(String type:List.of("","text/plain"))assertEquals(415,raw(h,path(ids[0]),bytes,type.isEmpty()?null:type,bearer,List.of(event),List.of(now),List.of(sig)).statusCode());assertEquals(413,raw(h,path(ids[0]),new byte[16385],"application/json",bearer,List.of(event),List.of(now),List.of(sig)).statusCode());
  assertEquals(400,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of(),List.of(now),List.of(sig)).statusCode());assertEquals(400,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of(event,event),List.of(now),List.of(sig)).statusCode());assertEquals(400,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of("<invalid>"),List.of(now),List.of(sig)).statusCode());for(String time:List.of("01","-1","n/a","9999999999999"))assertEquals(400,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of(event),List.of(time),List.of(sig)).statusCode());for(String time:List.of("0",Long.toString(System.currentTimeMillis()/1000+301)))assertEquals(403,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of(event),List.of(time),List.of(signature(ids[1],time,ids[0],event,bytes))).statusCode());for(String bad:List.of("bad","0".repeat(64),sig.toUpperCase(Locale.ROOT)))assertEquals(403,raw(h,path(ids[0]),bytes,"application/json",bearer,List.of(event),List.of(now),List.of(bad)).statusCode());assertEquals(403,raw(h,path(ids[0]),"{}".getBytes(StandardCharsets.UTF_8),"application/json",bearer,List.of(event),List.of(now),List.of(sig)).statusCode());
  for(Object input:List.of(map(),map("fields",map()),map("fields",map("short_description","x","state","1")),map("fields",map("short_description",1)),map("fields",map("short_description","")),map("fields",map("short_description","x"),"extra",1)))assertEquals(400,send(h,ids,"bad-body",input).statusCode());byte[] invalid="{".getBytes(StandardCharsets.UTF_8);assertEquals(400,raw(h,path(ids[0]),invalid,"application/json",bearer,List.of(event),List.of(now),List.of(signature(ids[1],now,ids[0],event,invalid))).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_signed_receipt"));db.update("UPDATE os_signed_profile SET envelope='unreadable' WHERE profile_id=?",ids[0]);db.connection.commit();}assertEquals(503,send(h,ids,event,payload()).statusCode());
 }
 static void configuration(WorkflowSupport h)throws Exception {
  var ids=setup(h);h.account("IntegrationReader","reader");assertEquals(200,h.get(API,auth("admin")).statusCode());assertEquals(200,h.get("/admin/integration-profiles?table=problem",auth("admin")).statusCode());assertEquals(403,h.get(API,auth("IntegrationReader")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?bad=1",auth("admin")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());assertEquals(409,h.json("POST",API+"/"+ids[0],config(2),auth("admin")).statusCode());
  for(var bad:List.of(map("extra",1),map("active","true"),map("revision","0"))){var input=config(0);input.putAll(bad);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());}assertEquals(400,h.json("POST",API,map("revision",0,"active",false),auth("admin")).statusCode());assertEquals(400,h.json("POST",API,map("revision",0,"operation","rotate"),auth("admin")).statusCode());assertEquals(400,h.json("POST",API+"/"+ids[0],map("revision",1,"operation","wrong"),auth("admin")).statusCode());
  for(var bad:List.of(map("extra",1),map("name",""),map("gateway_username","missing"),map("fields","all"),map("fields",List.of()),map("fields",Collections.nCopies(33,"short_description")),map("fields",List.of(1)),map("fields",List.of("unknown")),map("fields",List.of("short_description","short_description")),map("fields",List.of("description")))){var input=config(0);object(input.get("definition")).putAll(bad);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode(),bad.toString());}
  var wrong=config(0);object(wrong.get("definition")).put("gateway_username","admin");assertEquals(409,h.json("POST",API,wrong,auth("admin")).statusCode());var renamed=config(1);object(renamed.get("definition")).put("name","Revised unused intake");result(h.json("POST",API+"/"+ids[0],renamed,auth("admin")));assertEquals(302,h.protectedForm("/admin/integration-profiles/"+ids[0],map("revision","2","active","false"),auth("admin")).statusCode());assertEquals(403,send(h,ids,"disabled",payload()).statusCode());assertEquals(400,h.protectedForm("/admin/integration-profiles",map(),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/integration-profiles/"+ids[0],map("revision","3","active","bad"),auth("admin")).statusCode());assertEquals(200,h.protectedForm("/admin/integration-profiles/"+ids[0],map("revision","3","operation","rotate"),auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception {
  var ids=setup(h);var accepted=result(send(h,ids,"first",payload()));String record=object(accepted.get("record")).get("sys_id").toString();for(String mode:List.of("readonly","wrongtable","foreign")){String token;try(var db=h.store.open()){PlatformFoundationTest.bind(db);String user=ids[3];if(mode.equals("foreign")){Service.createAccount(db,map("name","ForeignGateway","password",PASSWORD,"role","agent"));user=RecordAccess.owner(db,"ForeignGateway");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",user);}var input=map("label",mode,"table",mode.equals("wrongtable")?"problem":"incident","days",1);token=(mode.equals("readonly")?ApiKeys.issue(db,db.viewerId,user,input):ApiKeyWrites.issue(db,db.viewerId,user,input)).get("token").toString();db.connection.commit();}var copy=ids.clone();copy[2]=token;assertEquals(403,send(h,copy,mode,payload()).statusCode());}
  var unknown=ids.clone();unknown[0]=id();assertEquals(404,send(h,unknown,"missing",payload()).statusCode());String other=object(result(h.json("POST",API,config(0),auth("admin"))).get("profile")).get("profile_id").toString();try(var db=h.store.open()){db.update("UPDATE os_signed_profile SET table_name='problem' WHERE profile_id=?",other);db.connection.commit();}var mismatch=ids.clone();mismatch[0]=other;assertEquals(403,send(h,mismatch,"wrong-profile-table",payload()).statusCode());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}for(String permission:List.of("read","create")){var schema=new LinkedHashMap<>(original);schema.put("record_roles",map(permission,List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,send(h,ids,"first",payload()).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}for(String permission:List.of("read_roles","write_roles")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map("description",map("type","string",permission,List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,send(h,ids,"first",payload()).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  ProblemInvestigationsAcceptance.access(h,"incident",record,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,send(h,ids,"first",payload()).statusCode());try(var db=h.store.open()){db.update("UPDATE os_api_key SET enabled=0 WHERE token_hash=?",Passwords.tokenHash(ids[2]));db.connection.commit();}assertEquals(401,send(h,ids,"revoked-key",payload()).statusCode());try(var db=h.store.open()){db.update("UPDATE os_api_key SET enabled=1 WHERE token_hash=?",Passwords.tokenHash(ids[2]));db.update("UPDATE os_user SET active=0 WHERE user_id=?",ids[3]);db.connection.commit();}assertEquals(401,send(h,ids,"revoked-account",payload()).statusCode());result(h.json("POST",API+"/"+ids[0],map("revision",1,"active",false),auth("admin")));assertEquals(0,object(result(h.get(API+"/"+ids[0],auth("admin"))).get("profile")).get("active"));
 }
 static void capacity(WorkflowSupport h)throws Exception {
  var ids=setup(h);result(send(h,ids,"first",payload()));try(var db=h.store.open()){var profile=db.one("SELECT * FROM os_signed_profile WHERE profile_id=?",ids[0]);for(int n=1;n<100;n++)db.update("INSERT INTO os_signed_profile(profile_id,name,table_name,gateway_id,definition,active,revision,envelope) VALUES(?,?,?,?,?,0,1,?)",id(),"Capacity "+n,"incident",ids[3],JSON.writeValueAsString(profile.get("definition")),profile.get("envelope"));var receipt=db.one("SELECT * FROM os_signed_receipt WHERE profile_id=?",ids[0]);try(var statement=db.connection.prepareStatement("INSERT INTO os_signed_receipt(profile_id,event_id,fingerprint,record_id,profile_revision,gateway_id,key_id,created) VALUES(?,?,?,?,1,?,?,?)")){for(int n=1;n<10000;n++){Object[] values={ids[0],"capacity-"+n,receipt.get("fingerprint"),receipt.get("record_id"),ids[3],receipt.get("key_id"),receipt.get("created")};for(int k=0;k<values.length;k++)statement.setObject(k+1,values[k]);statement.addBatch();}statement.executeBatch();}db.connection.commit();}assertEquals(400,h.json("POST",API,config(0),auth("admin")).statusCode());assertEquals(400,send(h,ids,"over-capacity",payload()).statusCode());assertEquals(true,result(send(h,ids,"first",payload())).get("duplicate"));var page=result(h.get(API+"/"+ids[0],auth("admin")));assertEquals(10000,((Number)page.get("total")).intValue());assertEquals(100,objects(page.get("receipts")).size());
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var ids=setup(h);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return result(send(h,ids,"concurrent",payload()));});var b=pool.submit(()->{start.await();return result(send(h,ids,"concurrent",payload()));});start.countDown();var first=a.get();var second=b.get();assertEquals(object(first.get("record")).get("sys_id"),object(second.get("record")).get("sys_id"));assertEquals(Set.of(true,false),Set.of(first.get("duplicate"),second.get("duplicate")));}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_signed_receipt"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_record WHERE \"table\"='incident'"));}
 }
 static void edges(WorkflowSupport h)throws Exception {
  var ids=setup(h);byte[] minimal=JSON.writeValueAsBytes(map("fields",map("short_description","Boundary signed record")));byte[] largest=new byte[16384];java.util.Arrays.fill(largest,(byte)' ');System.arraycopy(minimal,0,largest,0,minimal.length);long now=System.currentTimeMillis();
  for(int delta:new int[]{-300,300}){String event="time-edge-"+delta,time=Long.toString(now/1000+delta);try(var db=h.store.open()){var caller=ApiKeys.authenticate(db,"Bearer "+ids[2],path(ids[0]),"POST");db.viewerId=caller.get("user_id").toString();db.viewerRole="agent";var accepted=SignedEvents.receive(h.store,db,caller,"incident",ids[0],"application/json; charset=utf-8",List.of(event),List.of(time),List.of(signature(ids[1],time,ids[0],event,largest)),largest,now);assertEquals(false,accepted.get("duplicate"));db.connection.commit();}}
  String event="padded-http",time=Long.toString(System.currentTimeMillis()/1000);assertEquals(201,raw(h,path(ids[0]),largest,"application/json","Bearer "+ids[2],List.of(event),List.of(time),List.of(signature(ids[1],time,ids[0],event,largest))).statusCode());byte[] reordered=JSON.writeValueAsBytes(map("fields",map("priority","2","description","Provider evidence","short_description","Signed monitoring alert <script>")));result(send(h,ids,"field-order",payload()));assertEquals(200,raw(h,path(ids[0]),reordered,"application/json","Bearer "+ids[2],List.of("field-order"),List.of(time),List.of(signature(ids[1],time,ids[0],"field-order",reordered))).statusCode());
  var badForm=map("revision","0","active","true","name","Invalid form","table","incident","gateway_username","EventGateway","field_short_description","false");assertEquals(400,h.protectedForm("/admin/integration-profiles",badForm,auth("admin")).statusCode());badForm.put("field_short_description","true");badForm.put("extra","bad");assertEquals(400,h.protectedForm("/admin/integration-profiles",badForm,auth("admin")).statusCode());
  assertEquals("6d91118475e8a742916e0d866a0840056ed77b73e496a18cfe05fc101832ca96",HexFormat.of().formatHex(SignedEvents.signature("public protocol vector","1700000000","a".repeat(32),"vector-event","{\"fields\":{\"short_description\":\"x\"}}".getBytes(StandardCharsets.UTF_8))));
 }

}
